    /// When `parse_buffer_step` aborts on the deadline, the prior state
    /// passed via `&mut Option<_>` must remain populated so the caller
    /// can hand it to a follow-up parse without losing incrementality.
    #[test]
    fn parse_buffer_step_preserves_prior_on_deadline_abort() {
        let scheduler = Arc::new(stoat_scheduler::TestScheduler::new());
        let executor = scheduler.executor();
        let lang = LanguageRegistry::standard()
            .for_path(Path::new("a.rs"))
            .unwrap();
        let styles = SyntaxStyles::from_theme(&crate::theme::Theme::empty());
        let buffer_id = BufferId::new(1);

        let text = "fn a() {}\n".repeat(10_000);
        let mut buf = TextBuffer::with_text(buffer_id, &text);
        let snap1 = buf.snapshot.clone();

        let mut prior: Option<SyntaxState> = None;
        let mut prior_map: Option<stoat_language::SyntaxMap> = None;
        let out = parse_buffer_step(
            buffer_id,
            snap1,
            &lang,
            &mut prior,
            &mut prior_map,
            None,
            None,
            &styles,
            None,
        )
        .expect("first parse should succeed");
        let initial_version = out.syntax.version;

        let mut prior: Option<SyntaxState> = Some(out.syntax);
        let mut prior_map: Option<stoat_language::SyntaxMap> = Some(out.syntax_map);
        buf.edit(0..0, "// edit\n");
        let snap2 = buf.snapshot.clone();

        let deadline = executor.now();
        let result = parse_buffer_step(
            buffer_id,
            snap2.clone(),
            &lang,
            &mut prior,
            &mut prior_map,
            None,
            None,
            &styles,
            Some((deadline, &executor)),
        );
        assert!(result.is_none(), "expected deadline abort to return None");
        let prior_state = prior
            .as_ref()
            .expect("prior must survive deadline abort, was consumed");
        assert_eq!(
            prior_state.version, initial_version,
            "prior version must be unchanged",
        );
        assert!(
            prior_map.is_some(),
            "prior_syntax_map must survive deadline abort",
        );

        let recovery = parse_buffer_step(
            buffer_id,
            snap2,
            &lang,
            &mut prior,
            &mut prior_map,
            None,
            None,
            &styles,
            None,
        )
        .expect("recovery parse should succeed");
        assert!(recovery.syntax.version > initial_version);
        assert!(prior.is_none(), "successful parse must consume the prior");
        assert!(prior_map.is_none());
    }

    /// The deadline check inside `parse_rope_within` reads time from the
    /// `Executor`, not the wall clock, so `TestScheduler::advance_clock`
    /// drives the timeout deterministically.
    #[test]
    fn parse_buffer_step_deadline_uses_executor_clock() {
        use std::time::Duration;
        let scheduler = Arc::new(stoat_scheduler::TestScheduler::new());
        let executor = scheduler.executor();
        let lang = LanguageRegistry::standard()
            .for_path(Path::new("a.rs"))
            .unwrap();
        let styles = SyntaxStyles::from_theme(&crate::theme::Theme::empty());
        let buffer_id = BufferId::new(1);

        let text = "fn a() {}\n".repeat(10_000);
        let mut buf = TextBuffer::with_text(buffer_id, &text);
        let snap1 = buf.snapshot.clone();

        let mut prior: Option<SyntaxState> = None;
        let mut prior_map: Option<stoat_language::SyntaxMap> = None;
        let out = parse_buffer_step(
            buffer_id,
            snap1,
            &lang,
            &mut prior,
            &mut prior_map,
            None,
            None,
            &styles,
            None,
        )
        .expect("first parse should succeed");

        let mut prior: Option<SyntaxState> = Some(out.syntax);
        let mut prior_map: Option<stoat_language::SyntaxMap> = Some(out.syntax_map);
        buf.edit(0..0, "// edit\n");
        let snap2 = buf.snapshot.clone();

        let deadline = executor.now() + Duration::from_secs(3600);
        let succeeded = parse_buffer_step(
            buffer_id,
            snap2,
            &lang,
            &mut prior,
            &mut prior_map,
            None,
            None,
            &styles,
            Some((deadline, &executor)),
        )
        .expect("deadline far in the future should not abort");

        let mut prior: Option<SyntaxState> = Some(succeeded.syntax);
        let mut prior_map: Option<stoat_language::SyntaxMap> = Some(succeeded.syntax_map);
        buf.edit(0..0, "// edit2\n");
        let snap3 = buf.snapshot.clone();

        scheduler.advance_clock(Duration::from_secs(7200));

        let aborted = parse_buffer_step(
            buffer_id,
            snap3,
            &lang,
            &mut prior,
            &mut prior_map,
            None,
            None,
            &styles,
            Some((deadline, &executor)),
        );
        assert!(
            aborted.is_none(),
            "after advance_clock past the deadline, parse must abort",
        );
    }

    /// Parse `path`'s `original`, apply one edit, then reparse both ways:
    /// once carrying the first parse's state forward, once from nothing.
    /// Returns `(incremental, from_scratch)` token lists as resolved
    /// `(start, end, style)` triples against the post-edit snapshot.
    #[allow(clippy::type_complexity)]
    fn tokens_incremental_vs_fresh(
        path: &str,
        original: &str,
        edit_at: usize,
        inserted: &str,
    ) -> (
        Vec<(usize, usize, HighlightStyleId)>,
        Vec<(usize, usize, HighlightStyleId)>,
    ) {
        let styles = SyntaxStyles::from_theme(&crate::theme::Theme::empty());
        let registry = LanguageRegistry::standard();
        // Without this every capture resolves to HighlightId::DEFAULT and both
        // token lists come back empty, comparing equal for the wrong reason.
        install_highlight_maps(&registry, &styles);
        let lang = registry.for_path(Path::new(path)).unwrap();
        let buffer_id = BufferId::new(1);

        let mut buf = TextBuffer::with_text(buffer_id, original);
        let first = {
            let mut prior = None;
            let mut prior_map = None;
            parse_buffer_step(
                buffer_id,
                buf.snapshot.clone(),
                &lang,
                &mut prior,
                &mut prior_map,
                None,
                None,
                &styles,
                None,
            )
            .expect("first parse should succeed")
        };

        buf.edit(edit_at..edit_at, inserted);
        let edited = buf.snapshot.clone();

        let incremental = {
            let mut prior = Some(first.syntax);
            let mut prior_map = Some(first.syntax_map);
            parse_buffer_step(
                buffer_id,
                edited.clone(),
                &lang,
                &mut prior,
                &mut prior_map,
                None,
                None,
                &styles,
                None,
            )
            .expect("incremental parse should succeed")
        };
        let fresh = {
            let mut prior = None;
            let mut prior_map = None;
            parse_buffer_step(
                buffer_id,
                edited.clone(),
                &lang,
                &mut prior,
                &mut prior_map,
                None,
                None,
                &styles,
                None,
            )
            .expect("from-scratch parse should succeed")
        };

        let resolve = |out: &ParseJobOutput| {
            out.token_channel
                .tokens
                .iter()
                .map(|t| {
                    (
                        edited.resolve_anchor(&t.range.start),
                        edited.resolve_anchor(&t.range.end),
                        t.style,
                    )
                })
                .collect()
        };
        (resolve(&incremental), resolve(&fresh))
    }

    /// Reusing the prior [`stoat_language::SyntaxMap`] is only sound if it
    /// produces the highlights a full parse would. The incremental path
    /// re-walks just the edited rows for injection changes, so a divergence
    /// here means highlights outside that window were lost or went stale.
    #[test]
    fn incremental_parse_tokens_match_a_fresh_parse() {
        let original = "fn a() -> u32 {\n    let x = 1;\n    x\n}\n";
        let (incremental, fresh) =
            tokens_incremental_vs_fresh("a.rs", original, original.len(), "// tail\n");
        assert_eq!(
            incremental, fresh,
            "incremental tokens must equal a from-scratch parse",
        );
        assert!(!fresh.is_empty(), "fixture must produce tokens at all");
    }

    /// The injection layers are what the old drop-and-rebuild protected.
    /// A filtered reparse never re-walks the fence, so its rust highlights
    /// survive only if the layer is carried across the edit.
    #[test]
    fn incremental_parse_keeps_fenced_injection_tokens() {
        let original = "# Title\n\n```rust\nfn a() -> u32 { 1 }\n```\n\ntail\n";
        let (incremental, fresh) =
            tokens_incremental_vs_fresh("a.md", original, original.len(), "more tail\n");
        assert_eq!(
            incremental, fresh,
            "incremental tokens must equal a from-scratch parse across an injection",
        );

        let fence_body = original.find("fn a()").unwrap();
        assert!(
            fresh
                .iter()
                .any(|&(start, _, _)| start >= fence_body && start < fence_body + 20),
            "fixture must produce tokens inside the rust fence, got {fresh:?}",
        );
    }

    /// The state one parse hands the next so it can carry tokens across an
    /// edit rather than re-querying the file.
    struct CarriedParse {
        buffer_id: BufferId,
        syntax: Option<SyntaxState>,
        map: Option<stoat_language::SyntaxMap>,
        spans: Option<SemanticTokenSpans>,
        anchors: Option<Arc<[SemanticTokenHighlight]>>,
    }

    impl CarriedParse {
        fn new(buffer_id: BufferId) -> Self {
            Self {
                buffer_id,
                syntax: None,
                map: None,
                spans: None,
                anchors: None,
            }
        }
    }

    /// Parse `snapshot` twice, once carrying `state` forward and once from
    /// nothing, and assert the two agree on both the styled byte spans and the
    /// offsets every anchor resolves to. Leaves `state` holding the carried
    /// parse, ready for the next edit. Returns its layer count, which is the
    /// guard that decides whether the carry could narrow its query at all.
    fn assert_carried_parse_matches_fresh(
        state: &mut CarriedParse,
        snapshot: &TextBufferSnapshot,
        lang: &Arc<Language>,
        styles: &SyntaxStyles,
        step: &str,
    ) -> usize {
        let buffer_id = state.buffer_id;
        let carried = parse_buffer_step(
            buffer_id,
            snapshot.clone(),
            lang,
            &mut state.syntax,
            &mut state.map,
            state.spans.as_deref(),
            state.anchors.as_deref(),
            styles,
            None,
        )
        .expect("carried parse should succeed");

        let fresh = {
            let mut syntax = None;
            let mut map = None;
            parse_buffer_step(
                buffer_id,
                snapshot.clone(),
                lang,
                &mut syntax,
                &mut map,
                None,
                None,
                styles,
                None,
            )
            .expect("from-scratch parse should succeed")
        };

        assert_eq!(
            carried.token_spans, fresh.token_spans,
            "{step}: carried spans must equal a from-scratch parse",
        );
        let resolved = |out: &ParseJobOutput| -> Vec<(usize, usize, HighlightStyleId)> {
            out.token_channel
                .tokens
                .iter()
                .map(|t| {
                    (
                        snapshot.resolve_anchor(&t.range.start),
                        snapshot.resolve_anchor(&t.range.end),
                        t.style,
                    )
                })
                .collect()
        };
        assert_eq!(
            resolved(&carried),
            resolved(&fresh),
            "{step}: carried anchors must resolve where a from-scratch parse anchored",
        );

        let layers = carried.syntax_map.snapshot().layer_count();
        state.syntax = Some(carried.syntax);
        state.map = Some(carried.syntax_map);
        state.spans = Some(carried.token_spans);
        state.anchors = Some(carried.token_channel.tokens);
        layers
    }

    /// The theme-installed styles and language every carried-parse test parses
    /// against. Without the highlight maps every capture resolves to
    /// `HighlightId::DEFAULT` and both token lists come back empty, comparing
    /// equal for the wrong reason.
    fn carried_parse_fixture(path: &str) -> (SyntaxStyles, Arc<Language>) {
        let styles = SyntaxStyles::from_theme(&crate::theme::Theme::empty());
        let registry = LanguageRegistry::standard();
        install_highlight_maps(&registry, &styles);
        let lang = registry.for_path(Path::new(path)).unwrap();
        (styles, lang)
    }

    /// Narrowing the capture walk to the edited ranges is only sound if the
    /// result is what walking the file would have produced. Randomized edits
    /// are the check, because the ways a narrowing goes wrong (a capture
    /// reaching past its query range, a token abutting an insertion, a token
    /// deleted outright) are all boundary cases no hand-picked edit hits by
    /// accident.
    #[test]
    fn a_carried_parse_tracks_a_fresh_parse_through_random_edits() {
        // Snippets chosen to move token boundaries rather than plain text:
        // quotes and comment markers restyle text far from where they land.
        let layers = random_edits_tracking_a_fresh_parse(
            "a.rs",
            "fn main() {\n    let name = \"hello\";\n    let n = 1 + 2;\n\
             \n    println!(\"{name} {n}\");\n}\n\nfn other(x: u32) -> u32 {\n    x * 2\n}\n",
            &[
                "\"", "//", "let ", "fn ", "*/", "/*", "x", " ", "\n", "'", "}", "{",
            ],
        );
        assert!(
            layers.iter().all(|&l| l == 1),
            "a rust buffer with no doc comment stays single-layer, got {layers:?}",
        );
    }

    /// The same randomized check over a buffer whose tokens come from several
    /// layers at once.
    ///
    /// A combined injection is one layer over several host ranges, so an edit
    /// that reaches it has to leave the layer covering every one of them. Edits
    /// that open, rename, and delete fences all move which ranges those are.
    #[test]
    fn a_carried_parse_tracks_a_fresh_parse_across_injection_layers() {
        // Fence markers and info strings are in the snippet set because an
        // edit that opens or renames a fence is what moves the layer set.
        let layers = random_edits_tracking_a_fresh_parse(
            "a.md",
            "# Title\n\nSome **bold** prose.\n\n```rust\nfn a() -> u32 { 1 }\n\
             let s = \"text\";\n```\n\nmore *prose* here\n\n```\nplain\n```\n",
            &[
                "```", "```rust", "\"", "*", "`", "#", "fn ", "x", " ", "\n", "-", "]",
            ],
        );
        assert!(
            layers.iter().any(|&l| l > 1),
            "the fixture must actually inject layers, got {layers:?}",
        );
    }

    /// Drive randomized edits over `source`, asserting after each one that the
    /// carried parse still equals a from-scratch parse of the same snapshot.
    ///
    /// Returns the layer count each step's parse produced, so a caller can pin
    /// that the fixture exercised the shape it was chosen for.
    fn random_edits_tracking_a_fresh_parse(
        path: &str,
        source: &str,
        snippets: &[&str],
    ) -> Vec<usize> {
        let (styles, lang) = carried_parse_fixture(path);
        let buffer_id = BufferId::new(1);
        let mut buf = TextBuffer::with_text(buffer_id, source);

        let mut state = CarriedParse::new(buffer_id);
        let mut seed = 0x2545_f491_4f6c_dd1d_u64;
        let mut next = || {
            seed ^= seed << 13;
            seed ^= seed >> 7;
            seed ^= seed << 17;
            seed
        };

        (0..80)
            .map(|step| {
                let len = buf.snapshot.visible_text.len();
                let at = (next() as usize) % (len + 1);
                let at = buf.snapshot.visible_text.clip_offset(at, Bias::Left);
                if next() % 3 == 0 {
                    let end = buf
                        .snapshot
                        .visible_text
                        .clip_offset((at + 1 + (next() as usize) % 4).min(len), Bias::Right);
                    buf.edit(at..end, "");
                } else {
                    buf.edit(at..at, snippets[(next() as usize) % snippets.len()]);
                }

                assert_carried_parse_matches_fresh(
                    &mut state,
                    &buf.snapshot.clone(),
                    &lang,
                    &styles,
                    &format!("step {step}"),
                )
            })
            .collect()
    }

    /// An opened quote restyles every line after it until it closes, which no
    /// edit range names. Only the tree's own changed ranges reach that far, so
    /// this is the case a narrowing built on edit ranges alone gets wrong.
    #[test]
    fn a_carried_parse_follows_a_quote_opened_far_from_the_restyled_text() {
        let (styles, lang) = carried_parse_fixture("a.rs");
        let buffer_id = BufferId::new(1);
        let body = "fn a() { let x = 1; }\n".repeat(20);
        let mut buf = TextBuffer::with_text(buffer_id, &body);

        let mut state = CarriedParse::new(buffer_id);
        assert_carried_parse_matches_fresh(
            &mut state,
            &buf.snapshot.clone(),
            &lang,
            &styles,
            "first parse",
        );

        // A lone quote near the top swallows the rest of the file into one
        // string, restaining every row below an edit that touched one byte.
        buf.edit(9..9, "\"");
        assert_carried_parse_matches_fresh(
            &mut state,
            &buf.snapshot.clone(),
            &lang,
            &styles,
            "quote opened",
        );

        // Closing it hands all that text back to the code highlighting, the
        // same restyle in reverse.
        buf.edit(30..30, "\"");
        assert_carried_parse_matches_fresh(
            &mut state,
            &buf.snapshot.clone(),
            &lang,
            &styles,
            "quote closed",
        );
    }

    /// A capture can reach far outside the range that returned it, and the
    /// tokens nested inside it between there and the edit were never queried.
    /// Widening the query to what came back and asking again is what keeps
    /// them, so this is the case a single-pass narrowing silently drops.
    #[test]
    fn a_carried_parse_keeps_tokens_nested_inside_a_capture_the_edit_reached() {
        let (styles, lang) = carried_parse_fixture("a.rs");
        let buffer_id = BufferId::new(1);
        // Escape sequences are captured inside the string literal enclosing
        // them, so an edit at the string's tail pulls the whole literal into
        // the query's answer while leaving every escape before it unqueried.
        let source = "fn a() {\n    let s = \"\\n\\t\\n\\t\\n\\t padding tail\";\n}\n";
        let mut buf = TextBuffer::with_text(buffer_id, source);

        let mut state = CarriedParse::new(buffer_id);
        assert_carried_parse_matches_fresh(
            &mut state,
            &buf.snapshot.clone(),
            &lang,
            &styles,
            "first parse",
        );

        let at = source.find("tail").expect("fixture has a tail");
        buf.edit(at..at, "x");
        assert_carried_parse_matches_fresh(
            &mut state,
            &buf.snapshot.clone(),
            &lang,
            &styles,
            "edit inside the string's tail",
        );
    }

    /// An injection layer can restyle its whole range without the host tree
    /// changing at all, so the narrowing has nothing to key on and the parse
    /// has to walk the file. The fallback is what keeps a fenced buffer
    /// correct, and it must stay correct across edits like any other.
    #[test]
    fn a_multi_layer_buffer_still_matches_a_fresh_parse() {
        let (styles, lang) = carried_parse_fixture("a.md");
        let buffer_id = BufferId::new(1);
        let source = "# Title\n\n```rust\nfn a() -> u32 { 1 }\n```\n\ntail text\n";
        let mut buf = TextBuffer::with_text(buffer_id, source);

        let mut state = CarriedParse::new(buffer_id);
        let layers = assert_carried_parse_matches_fresh(
            &mut state,
            &buf.snapshot.clone(),
            &lang,
            &styles,
            "first parse",
        );
        assert!(
            layers > 1,
            "fixture must inject a layer so the fallback is what runs, got {layers}",
        );

        let tail = source.find("tail").expect("fixture has a tail");
        buf.edit(tail..tail, "more ");
        assert_carried_parse_matches_fresh(
            &mut state,
            &buf.snapshot.clone(),
            &lang,
            &styles,
            "edit outside the fence",
        );
    }

    /// An edit restyles text nowhere near itself when it opens a construct that
    /// runs to end of file. The injection walk only re-queries where it is told
    /// to look, and keeps every layer it could not have re-found, so a filter
    /// built from the edit span alone carries the invalidated layer forward
    /// stale.
    #[test]
    fn an_edit_that_swallows_a_distant_fence_drops_its_layer() {
        let (styles, lang) = carried_parse_fixture("a.md");
        let buffer_id = BufferId::new(1);
        let source = "# Title\n\nprose\n\n```rust\nfn a() -> u32 { 1 }\n```\n\ntail text\n";
        let mut buf = TextBuffer::with_text(buffer_id, source);

        let mut state = CarriedParse::new(buffer_id);
        let layers = assert_carried_parse_matches_fresh(
            &mut state,
            &buf.snapshot.clone(),
            &lang,
            &styles,
            "first parse",
        );
        assert!(
            layers > 1,
            "fixture must start with the rust fence injected, got {layers} layers",
        );

        // A bare fence above the rust one, rows away from it. Everything below
        // becomes one unnamed fenced block, so the rust layer has to go.
        let prose = source.find("prose").expect("fixture has prose");
        buf.edit(prose..prose, "```\n");
        assert_carried_parse_matches_fresh(
            &mut state,
            &buf.snapshot.clone(),
            &lang,
            &styles,
            "an opening fence above swallows the rust fence",
        );
    }

    /// The narrowing has to actually engage, not just agree with the full walk
    /// by falling back to it. This drives it directly, so a guard that quietly
    /// stopped admitting ordinary edits would show up here rather than as a
    /// silent return to per-keystroke full walks.
    #[test]
    fn a_local_edit_recaptures_rather_than_walking_the_file() {
        let (styles, lang) = carried_parse_fixture("a.rs");
        let buffer_id = BufferId::new(1);
        let body = "fn a() { let x = 1; }\n".repeat(20);
        let mut buf = TextBuffer::with_text(buffer_id, &body);

        let first = {
            let mut syntax = None;
            let mut map = None;
            parse_buffer_step(
                buffer_id,
                buf.snapshot.clone(),
                &lang,
                &mut syntax,
                &mut map,
                None,
                None,
                &styles,
                None,
            )
            .expect("first parse should succeed")
        };

        let at = body.find("let x").expect("fixture has a binding");
        buf.edit(at..at, "mut ");
        let snapshot = buf.snapshot.clone();
        let rope = snapshot.visible_text.clone();
        let edits = snapshot.edits_since(first.syntax.version);

        let mut edited_tree = first.syntax.tree.clone();
        language::edit_tree(
            &mut edited_tree,
            edits.edits(),
            &first.syntax.rope_snapshot,
            &rope,
        );
        let mut map = first.syntax_map.clone();
        map.interpolate(edits.edits(), &first.syntax.rope_snapshot, &rope);
        map.reparse(&rope, lang.clone(), snapshot.version, None, None)
            .expect("reparse should succeed");
        let tree = map
            .snapshot()
            .iter_layers()
            .next()
            .expect("a root layer")
            .tree
            .clone();

        let invalidated = invalidated_ranges(&edited_tree, &tree, &edits, rope.len());
        assert!(
            invalidated.iter().map(|r| r.end - r.start).sum::<usize>() < rope.len() / 2,
            "an edit to one line must invalidate a fraction of the file, got {invalidated:?}",
        );

        let recaptured = recapture_edited_ranges(
            map.snapshot(),
            &rope,
            &first.token_spans,
            &edits,
            invalidated,
            &styles,
        )
        .expect("a single-layer local edit must recapture");
        assert!(
            recaptured.carried_from.iter().any(Option::is_some),
            "a local edit must carry tokens rather than re-query them all",
        );
        assert_eq!(
            recaptured.spans,
            styled_capture_spans(
                map.snapshot()
                    .captures(0..rope.len(), &rope, |l| Some(&l.highlight_query)),
                &styles,
            ),
            "recaptured spans must equal the full capture walk",
        );
    }

    /// Parse `original`, apply one edit, parse again carrying the first
    /// parse's spans forward, and return the second parse's changed rows.
    fn changed_rows_after_edit(
        path: &str,
        original: &str,
        edit_at: usize,
        inserted: &str,
    ) -> Option<Range<u32>> {
        let styles = SyntaxStyles::from_theme(&crate::theme::Theme::empty());
        let registry = LanguageRegistry::standard();
        install_highlight_maps(&registry, &styles);
        let lang = registry.for_path(Path::new(path)).unwrap();
        let buffer_id = BufferId::new(1);

        let mut buf = TextBuffer::with_text(buffer_id, original);
        let first = {
            let mut prior = None;
            let mut prior_map = None;
            parse_buffer_step(
                buffer_id,
                buf.snapshot.clone(),
                &lang,
                &mut prior,
                &mut prior_map,
                None,
                None,
                &styles,
                None,
            )
            .expect("first parse should succeed")
        };

        buf.edit(edit_at..edit_at, inserted);
        let mut prior = Some(first.syntax);
        let mut prior_map = Some(first.syntax_map);
        parse_buffer_step(
            buffer_id,
            buf.snapshot.clone(),
            &lang,
            &mut prior,
            &mut prior_map,
            Some(&first.token_spans),
            Some(&first.token_channel.tokens),
            &styles,
            None,
        )
        .expect("second parse should succeed")
        .changed_token_rows
    }

    /// The minimap recolors the rows a parse reports, so a keystroke that
    /// restains one line must not name the rest of the file.
    #[test]
    fn a_local_edit_reports_only_its_own_rows() {
        let original = "fn a() {}\n".repeat(40);
        let row_20 = original
            .match_indices('\n')
            .nth(19)
            .map(|(i, _)| i + 1)
            .unwrap();

        let rows = changed_rows_after_edit("a.rs", &original, row_20, "let x = 1;\n")
            .expect("a second parse with prior spans reports its rows");
        assert_eq!(
            rows,
            20..21,
            "an inserted line restains itself and nothing above or below",
        );
    }

    /// An edit leaving every token identical still covers the row it touched,
    /// because carrying a span through the patch and resolving an anchor
    /// disagree exactly there. It must not widen past that row.
    #[test]
    fn an_edit_leaving_tokens_alone_reports_only_the_edited_row() {
        let original = "fn a() {}\n".repeat(40);
        let row_20 = original
            .match_indices('\n')
            .nth(19)
            .map(|(i, _)| i + 1)
            .unwrap();

        let rows = changed_rows_after_edit("a.rs", &original, row_20, "\n")
            .expect("a second parse with prior spans reports its rows");
        assert_eq!(
            rows,
            20..21,
            "a blank line adds no tokens, so only the row it split is suspect",
        );
    }

    /// The rows a parse reports have to reach the strip that paints them.
    ///
    /// Splices cannot show this. A sweep queues nothing for a row whose
    /// summary is unchanged, so a scoped sweep and a full one emit the same
    /// frames and differ only in how many rows they re-summarize. What the
    /// scope does change is whether the sweep finishes inside one sync. Past
    /// one chunk's worth of rows a full sweep has to span several, which the
    /// strip reports as still pending.
    #[test]
    fn an_edit_sweeps_without_spilling_past_one_sync() {
        let mut h = Stoat::test();
        let (tx, _rx) = tokio::sync::mpsc::unbounded_channel::<Vec<u8>>();
        h.stoat.set_apc_tx(tx);

        // More rows than one recolor chunk, so a full sweep cannot finish in
        // the single sync that follows the edit.
        let total = crate::minimap::RESYNC_CHUNK as usize + 500;
        let body: String = vec!["fn a() {}"; total].join("\n");
        let root = PathBuf::from("/minimap");
        let path = root.join("big.rs");
        h.fake_fs().insert_file(&path, body.as_bytes());
        h.stoat.active_workspace_mut().git_root = root;
        action_handlers::dispatch(&mut h.stoat, &OpenFile { path });
        h.settle();
        h.resize(80, 24);

        let _ = h.stoat.render();
        h.stoat.emit_apc_scene();
        for _ in 0..100 {
            h.stoat.emit_minimap();
            if !h.stoat.minimap_build_pending {
                break;
            }
        }
        assert!(
            !h.stoat.minimap_build_pending,
            "the fixture must settle its build and first full sweep",
        );

        // Insert a `let` on the second line, restaining that row alone.
        let (_, buffer_id) = h.stoat.focused_editor_ids().expect("a focused editor");
        {
            let buffer = h
                .stoat
                .active_workspace()
                .buffers
                .get(buffer_id)
                .expect("buffer");
            buffer.write().expect("poisoned").edit(10..10, "let z = 1;");
        }

        // One settle only spawns the parse. Installing its result takes another
        // trip through the background drive.
        let target = h
            .stoat
            .active_workspace()
            .buffers
            .get(buffer_id)
            .expect("buffer")
            .read()
            .expect("poisoned")
            .snapshot
            .version;
        for _ in 0..10 {
            h.stoat.drive_background();
            h.settle();
            if h.stoat.active_workspace().buffers.syntax_version(buffer_id) == Some(target) {
                break;
            }
        }
        assert_eq!(
            h.stoat.active_workspace().buffers.syntax_version(buffer_id),
            Some(target),
            "the edit's reparse must land before the strip can sweep for it",
        );

        h.stoat.emit_minimap();
        assert!(
            !h.stoat.minimap_build_pending,
            "a one-row recolor must not leave a multi-sync sweep outstanding",
        );
    }

    /// Every cursor a multi-cursor delete moves is carried through the same
    /// merged range list, so the answer is a binary search over a prefix sum
    /// rather than a walk per cursor. The four positions a target can occupy
    /// relative to the ranges are what that search has to get right.
    #[test]
    fn an_offset_moves_back_by_the_deletions_before_it() {
        // Deleting 2..5 and 10..14 removes three bytes then four.
        let ranges = [(2usize, 5usize), (10, 14)];
        let deleted_before = [0usize, 3, 7];
        let moved = |target| Stoat::offset_after_deletions(target, &ranges, &deleted_before);

        assert_eq!(moved(1), 1, "ahead of every range, nothing shifts it");
        assert_eq!(moved(3), 2, "inside a range, it collapses to that start");
        assert_eq!(moved(7), 4, "between ranges, only the first has passed");
        assert_eq!(moved(20), 13, "past both, both have passed");

        assert_eq!(moved(2), 2, "a target on a range's start is not inside it");
        assert_eq!(moved(5), 2, "a target on a range's end sits after it");
    }

    /// Without a prior parse to diff against there is no row information, and
    /// the strip has to fall back to recoloring everything.
    #[test]
    fn a_first_parse_reports_no_rows_at_all() {
        let styles = SyntaxStyles::from_theme(&crate::theme::Theme::empty());
        let registry = LanguageRegistry::standard();
        install_highlight_maps(&registry, &styles);
        let lang = registry.for_path(Path::new("a.rs")).unwrap();
        let buffer_id = BufferId::new(1);

        let buf = TextBuffer::with_text(buffer_id, "fn a() {}\n");
        let mut prior = None;
        let mut prior_map = None;
        let out = parse_buffer_step(
            buffer_id,
            buf.snapshot.clone(),
            &lang,
            &mut prior,
            &mut prior_map,
            None,
            None,
            &styles,
            None,
        )
        .expect("parse should succeed");

        assert_eq!(
            out.changed_token_rows, None,
            "a first parse cannot bound what it changed",
        );
    }

    /// The parse builds its token anchors and search index in batch, from byte
    /// offsets rather than per-anchor tree seeks. The result has to be the same
    /// channel the per-anchor construction produces, or viewport queries would
    /// bracket a different set of tokens than the highlights they paint.
    #[test]
    fn batched_parse_channel_matches_per_anchor_construction() {
        let styles = SyntaxStyles::from_theme(&crate::theme::Theme::empty());
        let registry = LanguageRegistry::standard();
        install_highlight_maps(&registry, &styles);
        let lang = registry.for_path(Path::new("a.rs")).unwrap();
        let buffer_id = BufferId::new(1);

        // Nested captures give the search index overlapping, out-of-order ends
        // to bracket, which a flat token stream would not exercise.
        let text =
            "fn outer() -> u32 {\n    let s = \"a string\";\n    if true { 1 } else { 2 }\n}\n";
        let buf = TextBuffer::with_text(buffer_id, text);
        let snapshot = buf.snapshot.clone();

        let out = {
            let mut prior = None;
            let mut prior_map = None;
            parse_buffer_step(
                buffer_id,
                snapshot.clone(),
                &lang,
                &mut prior,
                &mut prior_map,
                None,
                None,
                &styles,
                None,
            )
            .expect("parse should succeed")
        };
        assert!(
            out.token_channel.tokens.len() > 5,
            "fixture must produce a token stream worth indexing",
        );

        let resolve = |a: &Anchor| snapshot.resolve_anchor(a);
        let per_anchor = BufferSemanticTokens::new(
            out.token_channel.tokens.clone(),
            styles.interner.clone(),
            resolve,
        );

        for start in 0..=text.len() {
            for end in [start, start + 1, start + 40, text.len()] {
                let end = end.min(text.len());
                assert_eq!(
                    out.token_channel.overlap_bounds(&(start..end), resolve),
                    per_anchor.overlap_bounds(&(start..end), resolve),
                    "bounds must agree for {start}..{end}",
                );
            }
        }
    }

    #[test]
    fn minimap_emits_declare_and_line_summaries() {
        use stoatty_protocol::command::Command;

        let mut h = Stoat::test();
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel::<Vec<u8>>();
        h.stoat.set_apc_tx(tx);

        let root = std::path::PathBuf::from("/minimap");
        let path = root.join("a.txt");
        h.fake_fs().insert_file(&path, b"alpha\nbravo\ncharlie\n");
        h.stoat.active_workspace_mut().git_root = root;
        action_handlers::dispatch(&mut h.stoat, &OpenFile { path });
        h.settle();
        h.resize(120, 24);

        let _ = h.stoat.render();
        h.stoat.emit_apc_scene();
        h.stoat.emit_minimap();
        let first = drain_apc(&mut rx);
        assert!(
            first.iter().any(|cmd| matches!(cmd, Command::Minimap(_))),
            "the first frame declares the strip, got {first:?}"
        );
        assert!(
            first
                .iter()
                .any(|cmd| matches!(cmd, Command::MinimapLines(_))),
            "the first frame sends the initial line summaries, got {first:?}"
        );

        h.type_keys("i z");
        h.settle();
        let _ = h.stoat.render();
        h.stoat.emit_apc_scene();
        h.stoat.emit_minimap();
        let edited = drain_apc(&mut rx);
        assert!(
            edited
                .iter()
                .any(|cmd| matches!(cmd, Command::MinimapLines(_))),
            "an edit splices the changed line, got {edited:?}"
        );
    }

    #[test]
    fn detach_emits_window_open_and_reattach_emits_window_close() {
        use stoatty_protocol::command::Command;

        let mut h = Stoat::test();
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel::<Vec<u8>>();
        h.stoat.set_apc_tx(tx);
        h.stoat.window_ipc_connected = true;

        let path = std::path::PathBuf::from("/w/a.txt");
        h.fake_fs().insert_file(&path, b"hello\n");
        action_handlers::dispatch(&mut h.stoat, &OpenFile { path });
        h.settle();
        h.resize(80, 24);
        h.type_action("SplitRight()");
        h.settle();

        h.type_action("DetachPane()");
        h.stoat.emit_windows();
        let opened = drain_apc(&mut rx);
        assert!(
            opened.iter().any(|c| matches!(c, Command::WindowOpen(_))),
            "detach opens a window, got {opened:?}"
        );

        h.stoat.emit_windows();
        assert!(
            drain_apc(&mut rx).is_empty(),
            "an unchanged frame emits no window commands"
        );

        h.type_action("ReattachPane()");
        h.stoat.emit_windows();
        let closed = drain_apc(&mut rx);
        assert!(
            closed.iter().any(|c| matches!(c, Command::WindowClose(_))),
            "reattach closes the window, got {closed:?}"
        );
    }

    #[test]
    fn a_multi_chunk_minimap_build_completes_over_idle_emits() {
        use stoatty_protocol::command::Command;

        let mut h = Stoat::test();
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel::<Vec<u8>>();
        h.stoat.set_apc_tx(tx);

        // A file larger than one build chunk fills over several syncs.
        let total = 6000usize;
        let body: String = vec!["ln"; total].join("\n");
        let root = std::path::PathBuf::from("/minimap");
        let path = root.join("big.txt");
        h.fake_fs().insert_file(&path, body.as_bytes());
        h.stoat.active_workspace_mut().git_root = root;
        action_handlers::dispatch(&mut h.stoat, &OpenFile { path });
        h.settle();
        h.resize(80, 24);

        let _ = h.stoat.render();
        h.stoat.emit_apc_scene();
        h.stoat.emit_minimap();
        assert!(
            h.stoat.minimap_build_pending,
            "a multi-chunk file leaves the build pending after the first emit",
        );

        // Drive the build the way an idle frame tick does, gathering the lines
        // every emitted splice covers.
        let mut covered: Vec<u32> = Vec::new();
        for _ in 0..100 {
            for cmd in drain_apc(&mut rx) {
                if let Command::MinimapLines(lines) = cmd {
                    covered.extend(lines.start..lines.start + lines.lines.len() as u32);
                }
            }
            if !h.stoat.minimap_build_pending {
                break;
            }
            h.stoat.emit_minimap();
        }

        assert!(
            !h.stoat.minimap_build_pending,
            "the build completes over successive emits",
        );
        covered.sort_unstable();
        assert_eq!(
            covered,
            (0..total as u32).collect::<Vec<_>>(),
            "the emitted splices cover every line exactly once",
        );
    }

    /// A two-pane split with the second file focused, painted once so both
    /// panes' caches are warm.
    ///
    /// The unfocused pane's buffer carries a diagnostic, so its paint reaches
    /// all three channels. Without one it produces no undercurl span at all,
    /// and a replay that dropped them would pass unnoticed.
    fn split_pair(h: &mut crate::test_harness::TestHarness) {
        h.stoat.stoatty = true;
        h.resize(120, 16);
        let a = h.write_file("a.txt", "alpha\nbravo\ncharlie\n");
        let b = h.write_file("b.txt", "delta\necho\nfoxtrot\n");
        h.open_file(&a);
        publish_one_diagnostic(h, &a);
        h.type_action("SplitRight()");
        h.open_file(&b);
        h.settle();
        let _ = h.stoat.render();
    }

    /// An error over the first word of `path`'s first line, anchored against the
    /// buffer as it stands.
    fn publish_one_diagnostic(h: &mut crate::test_harness::TestHarness, path: &std::path::Path) {
        use lsp_types::{Diagnostic, DiagnosticSeverity, Position, Range as LspRange};

        let snapshot = {
            let ws = h.stoat.active_workspace();
            let id = ws.buffers.id_for_path(path).expect("buffer registered");
            ws.buffers
                .get(id)
                .expect("buffer")
                .read()
                .expect("poisoned")
                .snapshot
                .clone()
        };
        let anchors = crate::diagnostics::PublishedSpan {
            anchors: Some((
                snapshot.anchors_at_batch(&[0], Bias::Right)[0],
                snapshot.anchors_at_batch(&[5], Bias::Left)[0],
            )),
        };
        h.stoat.diagnostics.replace_from_server(
            path.to_path_buf(),
            "test".into(),
            vec![Diagnostic {
                range: LspRange {
                    start: Position {
                        line: 0,
                        character: 0,
                    },
                    end: Position {
                        line: 0,
                        character: 5,
                    },
                },
                severity: Some(DiagnosticSeverity::ERROR),
                message: String::new(),
                ..Default::default()
            }],
            vec![anchors],
        );
    }

    /// One frame's three output channels, for comparing a replayed frame
    /// against a repainted one.
    type FrameOutput = (Buffer, Vec<u8>, Vec<(u16, u16, u16, [u8; 3])>);

    fn frame_output(h: &mut crate::test_harness::TestHarness) -> FrameOutput {
        let buf = h.stoat.render();
        let scene = h.stoat.apc_scene.bytes().to_vec();
        let spans = h
            .stoat
            .pending_undercurls
            .spans()
            .iter()
            .map(|span| (span.x, span.y, span.len, span.color))
            .collect();
        (buf, scene, spans)
    }

    /// Replaying an unfocused pane produces the frame repainting it would have,
    /// while the focused pane alone is painted.
    ///
    /// A cache that skipped work but changed the output would be worse than no
    /// cache, so the comparison is against the same frame with the cache
    /// emptied rather than against a recorded expectation. All three channels
    /// are compared, since cells alone would pass while the rich gutter, the
    /// minimap strip, and the undercurls were dropped.
    #[test]
    fn a_replayed_pane_paints_what_repainting_it_would() {
        let mut h = Stoat::test();
        split_pair(&mut h);

        h.type_keys("i");
        h.type_text("X");
        h.settle();

        let painted_before = h.stoat.pane_paints;
        let replayed = frame_output(&mut h);
        assert_eq!(
            h.stoat.pane_paints - painted_before,
            1,
            "the edited pane painted and the other replayed",
        );

        h.stoat.pane_cache.clear();
        let painted_before = h.stoat.pane_paints;
        let repainted = frame_output(&mut h);
        assert_eq!(
            h.stoat.pane_paints - painted_before,
            2,
            "and with the cache emptied both panes paint",
        );

        assert_eq!(replayed.0, repainted.0, "the cells match");
        assert_eq!(replayed.1, repainted.1, "the scene bytes match");
        assert_eq!(replayed.2, repainted.2, "the undercurl spans match");
    }

    /// A frame driven by background activity alone paints only the focused
    /// pane.
    ///
    /// Typing in insert mode is the busiest thing the editor does, and a
    /// printable character never consults the keymap, so it must not pay to
    /// derive the lookup. Nothing else would notice if it started to: the
    /// derivation only costs time.
    ///
    /// The keys that do read a binding still derive one, which is what says the
    /// counter is measuring something.
    #[test]
    fn typing_a_printable_character_never_derives_a_keymap_lookup() {
        use crate::test_harness::TestHarness;

        let mut h = TestHarness::with_size(40, 6);
        let file = h.write_file("a.rs", "hello\n");
        h.open_file(&file);

        // `i` is a normal-mode binding and reads its own lookup.
        h.type_keys("i");
        let entering_insert = h.stoat.keymap_lookups.get();
        assert!(
            entering_insert > 0,
            "entering insert resolves through the keymap"
        );

        h.type_text("abcdef");
        assert_eq!(
            h.stoat.keymap_lookups.get(),
            entering_insert,
            "six printable characters must derive no lookup between them"
        );

        // Escape is non-printable, so it falls through to the keymap.
        h.type_keys("esc");
        assert!(
            h.stoat.keymap_lookups.get() > entering_insert,
            "leaving insert resolves through the keymap"
        );
    }

    /// This is the case the cache exists for. A spinner tick redraws at its own
    /// rate while nothing a pane reads has moved, and every visible pane used to
    /// repaint in full for it. The focused one still paints, since its
    /// selections and cursor are outside the key, so the saving is every pane
    /// but that one.
    #[test]
    fn a_background_tick_paints_only_the_focused_pane() {
        let mut h = Stoat::test();
        split_pair(&mut h);

        let before = h.stoat.pane_paints;
        h.stoat.spinner_clock += 1.0;
        let _ = h.stoat.render();

        assert_eq!(
            h.stoat.pane_paints - before,
            1,
            "the spinner moved nothing the unfocused pane reads",
        );
    }

    /// Every input a pane paints from reaches its key.
    ///
    /// A key that ignored one of these would leave a pane showing stale content
    /// with nothing to say it had, which is why each is moved through the real
    /// session rather than by building two keys by hand.
    ///
    /// The assertion is on the key rather than on a paint count, because the
    /// harness renders a frame per keystroke and the search case is several of
    /// them. A key that moved is a replay refused, since the lookup compares
    /// keys for equality before it hands anything back.
    #[test]
    fn each_input_that_moves_reaches_the_key() {
        type Case = (&'static str, fn(&mut crate::test_harness::TestHarness));
        let cases: [Case; 6] = [
            ("theme", |h| {
                action_handlers::dispatch(
                    &mut h.stoat,
                    &stoat_action::SetTheme {
                        name: "gruvbox-light".to_string(),
                    },
                );
            }),
            ("search", |h| {
                h.type_keys("/");
                h.type_text("alpha");
                h.type_keys("enter");
            }),
            ("inactive dim", |h| {
                h.stoat.settings.ui_inactive_dim = Some(0.6);
            }),
            ("line numbers", |h| {
                h.stoat.settings.editor_line_numbers = Some(LineNumbers::Off);
            }),
            ("diagnostics", |h| {
                let path = h.stoat.active_workspace().git_root.join("a.txt");
                h.stoat.diagnostics.replace_from_server(
                    path,
                    "test".into(),
                    Vec::new(),
                    Vec::new(),
                );
            }),
            ("the unfocused pane's own text", |h| {
                let ws = h.stoat.active_workspace_mut();
                let first = ws.panes.split_pane_ids()[0];
                let editor_id = match ws.panes.pane(first).view {
                    View::Editor(id) => id,
                    _ => panic!("the first pane holds an editor"),
                };
                let buffer_id = ws.editors.get(editor_id).expect("editor").buffer_id;
                let buffer = ws.buffers.get(buffer_id).expect("buffer");
                buffer.write().expect("poisoned").edit(0..0, "Z");
            }),
        ];

        for (what, apply) in cases {
            let mut h = Stoat::test();
            split_pair(&mut h);
            let _ = h.stoat.render();

            let unfocused = {
                let ws = h.stoat.active_workspace();
                let focused = ws.panes.focus();
                ws.panes
                    .split_pane_ids()
                    .into_iter()
                    .find(|id| *id != focused)
                    .expect("the split has an unfocused pane")
            };
            let before = h
                .stoat
                .pane_cache
                .get(&unfocused)
                .expect("the unfocused pane cached its paint")
                .key;

            apply(&mut h);
            h.settle();
            let _ = h.stoat.render();

            let after = h
                .stoat
                .pane_cache
                .get(&unfocused)
                .expect("and cached it again")
                .key;
            assert_ne!(
                before, after,
                "{what} has to reach the unfocused pane's key"
            );
        }
    }

    #[test]
    fn unfocused_pane_dims_its_minimap_declaration() {
        use crate::render::review::{dim_rgb, style_rgb};
        use stoatty_protocol::command::{Command, MinimapCommand};

        let mut h = Stoat::test();
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel::<Vec<u8>>();
        h.stoat.set_apc_tx(tx);
        h.stoat.settings.editor_minimap = Some(MinimapMode::PerPane);
        // Wide enough that each vertical split clears the minimap min-width gate.
        h.resize(260, 24);

        let a = h.write_file("a.txt", "alpha\nbravo\ncharlie\n");
        let b = h.write_file("b.txt", "delta\necho\nfoxtrot\n");
        h.open_file(&a);
        h.type_action("SplitRight()");
        h.open_file(&b);
        h.settle();

        // 0.25 is the default ui.inactive_dim the test harness resolves.
        let dim = 0.25_f32;
        let bg = style_rgb(
            h.stoat
                .theme
                .try_get(crate::theme::scope::UI_BACKGROUND)
                .and_then(|s| s.bg),
        )
        .expect("test theme has an rgb background");
        let raw: Vec<[u8; 3]> = h.stoat.minimap_class_table.palette().to_vec();
        let dimmed: Vec<[u8; 3]> = raw.iter().map(|&c| dim_rgb(c, bg, dim)).collect();
        assert_ne!(raw, dimmed, "dim must actually change the palette");

        let _ = h.stoat.render();
        h.stoat.emit_apc_scene();
        let minimaps: Vec<MinimapCommand> = drain_apc(&mut rx)
            .into_iter()
            .filter_map(|c| match c {
                Command::Minimap(m) => Some(m),
                _ => None,
            })
            .collect();

        let focused = minimaps
            .iter()
            .find(|m| m.palette == raw)
            .expect("the focused pane keeps the raw palette");
        let unfocused = minimaps
            .iter()
            .find(|m| m.palette == dimmed)
            .expect("the unfocused pane dims the palette");

        let [tr, tg, tb, ta] = focused.thumb;
        let [dr, dg, db] = dim_rgb([tr, tg, tb], bg, dim);
        assert_eq!(
            unfocused.thumb,
            [dr, dg, db, ta],
            "the unfocused thumb dims its rgb and keeps its alpha"
        );
        assert_eq!(
            unfocused.thumb_border,
            [dr, dg, db],
            "the unfocused thumb border dims"
        );

        // The blend is held across frames rather than redone on each one, so a
        // change to the dim has to reach the next frame instead of the first
        // blend standing for the rest of the session.
        let widened = 0.6_f32;
        h.stoat.settings.ui_inactive_dim = Some(widened.into());
        let _ = h.stoat.render();
        h.stoat.emit_apc_scene();
        let rewidened: Vec<[u8; 3]> = raw.iter().map(|&c| dim_rgb(c, bg, widened)).collect();
        assert!(
            drain_apc(&mut rx)
                .into_iter()
                .any(|c| matches!(c, Command::Minimap(m) if m.palette == rewidened)),
            "a changed dim re-blends the held palette",
        );
    }

    #[test]
    fn single_minimap_mode_reserves_a_right_edge_band() {
        use stoat_config::MinimapMode;

        let mut h = Stoat::test();
        let (tx, _rx) = tokio::sync::mpsc::unbounded_channel::<Vec<u8>>();
        h.stoat.set_apc_tx(tx);
        h.stoat.settings.editor_minimap = Some(MinimapMode::Single);
        h.resize(200, 24);

        let a = h.write_file("a.txt", "alpha\nbravo\n");
        let b = h.write_file("b.txt", "delta\necho\n");
        h.open_file(&a);
        h.type_action("SplitRight()");
        h.open_file(&b);
        h.settle();
        let _ = h.stoat.render();

        let full = h.stoat.size();
        let band = h
            .stoat
            .single_minimap_rect
            .expect("single mode reserves a band");
        assert_eq!(
            band.x + band.width,
            full.width,
            "the band ends at the window right edge"
        );
        assert_eq!(band.y, full.y);
        assert_eq!(
            band.height,
            full.height - 1,
            "the band stops one row above the bottom status row"
        );
        assert!(band.width > 0, "the band has a real width");

        let focused_area = focused_editor_pane_area(&h);
        assert!(
            focused_area.x + focused_area.width <= band.x,
            "the focused pane stays left of the reserved band"
        );
        assert!(
            h.stoat
                .active_workspace()
                .editors
                .values()
                .all(|e| e.minimap_rect.is_none()),
            "single mode reserves no per-pane strips"
        );
    }

    #[test]
    fn single_minimap_band_leaves_the_bottom_status_row_full_width() {
        use stoat_config::MinimapMode;

        let mut h = Stoat::test();
        let (tx, _rx) = tokio::sync::mpsc::unbounded_channel::<Vec<u8>>();
        h.stoat.set_apc_tx(tx);
        h.stoat.settings.editor_minimap = Some(MinimapMode::Single);
        h.resize(200, 24);

        let a = h.write_file("a.txt", "alpha\nbravo\n");
        h.open_file(&a);
        h.settle();

        let size = h.stoat.size();
        let status_bg = h
            .stoat
            .theme
            .get(crate::theme::scope::UI_STATUSBAR_FOCUSED)
            .bg
            .expect("theme has a focused status background");

        let buf = h.stoat.render();

        let band = h
            .stoat
            .single_minimap_rect
            .expect("single mode reserves a band");
        assert_eq!(
            band.height,
            size.height - 1,
            "the band stops one row above the bottom status row"
        );

        let bottom = size.height - 1;
        assert_eq!(
            buf[(size.width - 1, bottom)].bg,
            status_bg,
            "the focused status bar reaches the window's last column"
        );
    }

    #[test]
    fn single_minimap_mode_declares_one_strip_following_focus() {
        use stoat_config::MinimapMode;
        use stoatty_protocol::command::Command;

        let content_id = |h: &Stoat| -> u32 {
            let (editor_id, _) = h.focused_editor_ids().expect("focused editor");
            let buffer_id = h
                .active_workspace()
                .editors
                .get(editor_id)
                .expect("editor")
                .buffer_id;
            h.minimap_content
                .get(&(h.active_workspace, buffer_id))
                .expect("minimap content for the focused buffer")
                .content_id()
        };
        let single_strips = |cmds: &[Command]| -> Vec<u32> {
            cmds.iter()
                .filter_map(|c| match c {
                    Command::Minimap(m) if m.strip_id == u32::MAX => Some(m.content_id),
                    _ => None,
                })
                .collect()
        };

        let mut h = Stoat::test();
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel::<Vec<u8>>();
        h.stoat.set_apc_tx(tx);
        h.stoat.settings.editor_minimap = Some(MinimapMode::Single);
        h.resize(200, 24);

        let a = h.write_file("a.txt", "alpha\nbravo\ncharlie\n");
        let b = h.write_file("b.txt", "delta\necho\nfoxtrot\n");
        h.open_file(&a);
        h.type_action("SplitRight()");
        h.open_file(&b);
        h.settle();

        let _ = h.stoat.render();
        h.stoat.emit_apc_scene();
        let cmds = drain_apc(&mut rx);
        assert!(
            cmds.iter()
                .all(|c| !matches!(c, Command::Minimap(m) if m.strip_id != u32::MAX)),
            "single mode declares no per-pane strips, got {cmds:?}"
        );
        let b_content = content_id(&h.stoat);
        assert_eq!(
            single_strips(&cmds).last().copied(),
            Some(b_content),
            "the single strip shows the focused buffer"
        );

        h.type_action("FocusNext()");
        h.settle();
        let _ = h.stoat.render();
        h.stoat.emit_apc_scene();
        let cmds = drain_apc(&mut rx);
        let a_content = content_id(&h.stoat);
        assert_ne!(a_content, b_content, "the two panes show different buffers");
        assert_eq!(
            single_strips(&cmds).last().copied(),
            Some(a_content),
            "the strip redeclares for the newly focused buffer"
        );
    }

    #[test]
    fn minimap_syntax_version_separates_unparsed_from_parsed_at_zero() {
        let base = minimap_syntax_version(true, None, None);
        assert_eq!(
            base,
            minimap_syntax_version(true, None, None),
            "identical inputs leave the built rows alone"
        );
        assert_ne!(
            base,
            minimap_syntax_version(true, Some(0), None),
            "the first parse of an unedited buffer recolors the strip"
        );
        assert_ne!(
            minimap_syntax_version(true, Some(0), None),
            minimap_syntax_version(true, Some(1), None),
            "a reparse after an edit recolors the strip"
        );
        assert_ne!(
            base,
            minimap_syntax_version(true, None, Some(0)),
            "the first LSP semantic tokens for an unedited buffer recolor the strip"
        );
        assert_ne!(
            minimap_syntax_version(true, Some(0), Some(0)),
            minimap_syntax_version(true, Some(0), Some(1)),
            "LSP tokens for a newer buffer version recolor the strip"
        );
        assert_ne!(
            base,
            minimap_syntax_version(false, None, None),
            "toggling syntax highlighting recolors the strip"
        );
    }

    #[test]
    fn minimap_drops_content_when_the_buffer_closes() {
        use stoatty_protocol::command::Command;

        let mut h = Stoat::test();
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel::<Vec<u8>>();
        h.stoat.set_apc_tx(tx);

        let root = std::path::PathBuf::from("/minimap-drop");
        let a = root.join("a.txt");
        let b = root.join("b.txt");
        h.fake_fs().insert_file(&a, b"alpha\nbravo\n");
        h.fake_fs().insert_file(&b, b"charlie\ndelta\n");
        h.stoat.active_workspace_mut().git_root = root;
        action_handlers::dispatch(&mut h.stoat, &OpenFile { path: a });
        action_handlers::dispatch(&mut h.stoat, &OpenFile { path: b });
        h.settle();
        h.resize(80, 24);
        let _ = h.stoat.render();
        h.stoat.emit_apc_scene();
        h.stoat.emit_minimap();
        let _ = drain_apc(&mut rx);

        action_handlers::dispatch(&mut h.stoat, &stoat_action::CloseBuffer);
        h.settle();
        let _ = h.stoat.render();
        h.stoat.emit_minimap();
        let closed = drain_apc(&mut rx);
        assert!(
            closed
                .iter()
                .any(|cmd| matches!(cmd, Command::MinimapDrop(_))),
            "closing a buffer drops its minimap content, got {closed:?}"
        );
    }

    #[test]
    fn minimap_view_tracks_the_scroll_position() {
        use stoatty_protocol::command::Command;

        let mut h = Stoat::test();
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel::<Vec<u8>>();
        h.stoat.set_apc_tx(tx);

        let root = std::path::PathBuf::from("/minimap-view");
        let path = root.join("a.txt");
        let body: String = (0..200).map(|i| format!("line {i}\n")).collect();
        h.fake_fs().insert_file(&path, body.as_bytes());
        h.stoat.active_workspace_mut().git_root = root;
        action_handlers::dispatch(&mut h.stoat, &OpenFile { path });
        h.settle();
        h.resize(120, 24);

        let _ = h.stoat.render();
        h.stoat.emit_smooth_scroll();
        let first = drain_apc(&mut rx);
        let top_at_origin = first.iter().find_map(|cmd| match cmd {
            Command::MinimapView(v) => Some(v.top_256),
            _ => None,
        });
        assert_eq!(
            top_at_origin,
            Some(0),
            "the origin thumb sits at line 0, got {first:?}"
        );

        let editor_id = h.stoat.focused_editor_ids().expect("focused editor").0;
        {
            let editor = h
                .stoat
                .active_workspace_mut()
                .editors
                .get_mut(editor_id)
                .expect("editor");
            editor.scroll_row = 50;
            editor.scroll_offset = 50.0;
        }
        let _ = h.stoat.render();
        h.stoat.emit_smooth_scroll();
        let scrolled = drain_apc(&mut rx);
        let top_after_scroll = scrolled.iter().find_map(|cmd| match cmd {
            Command::MinimapView(v) => Some(v.top_256),
            _ => None,
        });
        assert_eq!(
            top_after_scroll,
            Some(50 * 256),
            "the thumb tracks the scrolled top row, got {scrolled:?}"
        );
    }

    /// Several soft-wrapped display rows share one buffer line, and the strip
    /// draws one row per buffer line. An unconverted display top therefore
    /// overruns the strip's scrollable span near the bottom of the file, which
    /// pushes the thumb past the strip's bottom edge entirely.
    #[test]
    fn minimap_view_maps_wrapped_rows_to_buffer_lines() {
        use stoatty_protocol::command::Command;

        fn view_after_scroll(
            h: &mut crate::test_harness::TestHarness,
            rx: &mut UnboundedReceiver<Vec<u8>>,
            editor_id: EditorId,
            display_row: u32,
        ) -> (u32, u16) {
            let _ = drain_apc(rx);
            {
                let editor = h
                    .stoat
                    .active_workspace_mut()
                    .editors
                    .get_mut(editor_id)
                    .expect("editor");
                editor.scroll_row = display_row;
                editor.scroll_offset = display_row as f32;
            }
            let _ = h.stoat.render();
            h.stoat.emit_smooth_scroll();
            let cmds = drain_apc(rx);
            cmds.iter()
                .rev()
                .find_map(|cmd| match cmd {
                    Command::MinimapView(v) => Some((v.top_256, v.visible_lines)),
                    _ => None,
                })
                .unwrap_or_else(|| panic!("a minimap view emit, got {cmds:?}"))
        }

        let mut h = Stoat::test();
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel::<Vec<u8>>();
        h.stoat.set_apc_tx(tx);

        let root = std::path::PathBuf::from("/minimap-wrap");
        let path = root.join("wide.txt");
        // No trailing newline, so every buffer line is a long one and the wrap
        // ratio stays uniform across the file.
        let body = (0..60)
            .map(|i| format!("{i}{}", "w".repeat(150)))
            .collect::<Vec<_>>()
            .join("\n");
        h.fake_fs().insert_file(&path, body.as_bytes());
        h.stoat.active_workspace_mut().git_root = root;
        action_handlers::dispatch(&mut h.stoat, &OpenFile { path });
        h.settle();
        // Wide enough for the minimap strip to render at all, so the wrap comes
        // from the line length rather than a cramped pane.
        h.resize(120, 24);
        let _ = h.stoat.render();

        let editor_id = h.stoat.focused_editor_ids().expect("focused editor").0;
        // The emit measures the window against the pool region, so the expected
        // spans below must be derived from that same height.
        let pool_rows = {
            let panes = h.stoat.editor_pool_panes();
            let (_, _, region) = panes[0];
            region.height as u32
        };
        let (display_rows, buffer_lines, mid, bottom) = {
            let editor = h
                .stoat
                .active_workspace_mut()
                .editors
                .get_mut(editor_id)
                .expect("editor");
            let snapshot = editor.display_map.snapshot();
            let display_rows = snapshot.line_count();
            let line_at = |row: u32| {
                snapshot
                    .display_to_buffer(DisplayPoint::new(row, 0))
                    .expect("a text row")
                    .row
            };
            // The top display row, its buffer line, and the buffer lines the
            // pooled viewport covers from there.
            let window = |top_row: u32| {
                let last = (top_row + pool_rows - 1).min(display_rows - 1);
                (
                    top_row,
                    line_at(top_row),
                    line_at(last) - line_at(top_row) + 1,
                )
            };
            let max_scroll = display_rows
                .saturating_sub(1)
                .saturating_sub(pool_rows.saturating_sub(1));
            (
                display_rows,
                snapshot.buffer_line_count(),
                window(display_rows / 2),
                window(max_scroll),
            )
        };
        assert_eq!(
            display_rows,
            buffer_lines * 2,
            "the fixture must soft-wrap every line into exactly two display rows"
        );

        let (mid_row, mid_line, mid_visible) = mid;
        let emitted = view_after_scroll(&mut h, &mut rx, editor_id, mid_row);
        assert_eq!(
            emitted,
            (mid_line * 256, mid_visible as u16),
            "display row {mid_row} maps to buffer line {mid_line} over {mid_visible} lines"
        );

        let (max_row, max_line, max_visible) = bottom;
        let (top_256, visible) = view_after_scroll(&mut h, &mut rx, editor_id, max_row);
        assert_eq!(
            (top_256, visible),
            (max_line * 256, max_visible as u16),
            "the bottom-scrolled top maps to buffer line {max_line} over {max_visible} lines"
        );
        assert_eq!(
            top_256 / 256 + visible as u32,
            buffer_lines,
            "the bottom-scrolled window ends exactly at the last buffer line, so the thumb \
             stays on the strip"
        );
    }

    #[test]
    fn single_minimap_mode_syncs_content_for_every_visible_buffer() {
        use stoat_config::MinimapMode;
        use stoatty_protocol::command::Command;

        let mut h = Stoat::test();
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel::<Vec<u8>>();
        h.stoat.set_apc_tx(tx);
        h.stoat.settings.editor_minimap = Some(MinimapMode::Single);
        h.resize(200, 24);

        let a = h.write_file("a.txt", "alpha\nbravo\ncharlie\n");
        let b = h.write_file("b.txt", "delta\necho\nfoxtrot\n");
        h.open_file(&a);
        h.type_action("SplitRight()");
        h.open_file(&b);
        h.settle();
        let _ = h.stoat.render();

        let buffer_ids: Vec<BufferId> = {
            let ws = h.stoat.active_workspace();
            ws.panes
                .split_panes()
                .filter_map(|(_, pane)| match pane.view {
                    View::Editor(editor_id) => Some(ws.editors.get(editor_id)?.buffer_id),
                    _ => None,
                })
                .collect()
        };
        assert_eq!(buffer_ids.len(), 2, "two visible editor buffers");
        let content_ids: Vec<u32> = buffer_ids
            .iter()
            .map(|&buffer_id| {
                h.stoat
                    .minimap_content
                    .get(&(h.stoat.active_workspace, buffer_id))
                    .expect("content for a visible buffer")
                    .content_id()
            })
            .collect();

        h.stoat.emit_minimap();
        let synced: std::collections::HashSet<u32> = drain_apc(&mut rx)
            .iter()
            .filter_map(|c| match c {
                Command::MinimapLines(l) => Some(l.content_id),
                _ => None,
            })
            .collect();
        for id in content_ids {
            assert!(
                synced.contains(&id),
                "single mode syncs minimap_lines for every visible buffer; missing {id}, got {synced:?}"
            );
        }
    }

    #[test]
    fn single_minimap_view_follows_focus_and_rekeys_by_strip() {
        use stoat_config::MinimapMode;
        use stoatty_protocol::command::Command;

        let single_views = |cmds: &[Command]| -> Vec<u32> {
            cmds.iter()
                .filter_map(|c| match c {
                    Command::MinimapView(v) if v.strip_id == u32::MAX => Some(v.top_256),
                    _ => None,
                })
                .collect()
        };

        let mut h = Stoat::test();
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel::<Vec<u8>>();
        h.stoat.set_apc_tx(tx);
        h.stoat.settings.editor_minimap = Some(MinimapMode::Single);
        h.resize(200, 24);

        let a = h.write_file("a.txt", "alpha\nbravo\ncharlie\n");
        let b = h.write_file("b.txt", "delta\necho\nfoxtrot\n");
        h.open_file(&a);
        h.type_action("SplitRight()");
        h.open_file(&b);
        h.settle();

        let _ = h.stoat.render();
        h.stoat.emit_smooth_scroll();
        let cmds = drain_apc(&mut rx);
        assert_eq!(
            single_views(&cmds).last().copied(),
            Some(0),
            "single mode emits a view frame for strip u32::MAX at the origin"
        );
        assert!(
            cmds.iter()
                .all(|c| !matches!(c, Command::MinimapView(v) if v.strip_id != u32::MAX)),
            "single mode emits no per-pane view frames, got {cmds:?}"
        );

        // Focus the other pane, also at offset 0. Without keying the dedup by
        // strip and storing the pool, the shared strip would skip this frame as
        // an unmoved viewport. The pool change forces the re-emit.
        h.type_action("FocusNext()");
        h.settle();
        let _ = h.stoat.render();
        h.stoat.emit_smooth_scroll();
        let cmds = drain_apc(&mut rx);
        assert_eq!(
            single_views(&cmds).last().copied(),
            Some(0),
            "focusing another pane at the same offset re-emits the strip view"
        );
    }

    #[test]
    fn a_centered_modal_undeclares_the_single_strip() {
        use stoat_action::OpenFileFinder;
        use stoat_config::MinimapMode;
        use stoatty_protocol::command::Command;

        let strip_declared = |cmds: &[Command]| -> bool {
            cmds.iter()
                .any(|c| matches!(c, Command::Minimap(m) if m.strip_id == u32::MAX))
        };

        let mut h = Stoat::test();
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel::<Vec<u8>>();
        h.stoat.set_apc_tx(tx);
        h.stoat.settings.editor_minimap = Some(MinimapMode::Single);
        h.resize(200, 24);

        let a = h.write_file("a.txt", "alpha\nbravo\ncharlie\n");
        h.open_file(&a);
        h.settle();

        let _ = h.stoat.render();
        h.stoat.emit_apc_scene();
        assert!(
            strip_declared(&drain_apc(&mut rx)),
            "single mode declares the strip while no modal is open"
        );

        action_handlers::dispatch(&mut h.stoat, &OpenFileFinder);
        h.settle();
        let _ = h.stoat.render();
        h.stoat.emit_apc_scene();
        assert!(
            !strip_declared(&drain_apc(&mut rx)),
            "opening the finder undeclares the strip so the modal owns the right edge"
        );

        h.stoat.file_finder = None;
        let _ = h.stoat.render();
        h.stoat.emit_apc_scene();
        assert!(
            strip_declared(&drain_apc(&mut rx)),
            "closing the finder redeclares the strip"
        );
    }

    /// The palette is the one centered modal that does not hide the strip.
    ///
    /// Its box is capped at 80 columns and centered, so it cannot reach a band
    /// that only exists from 108 columns up. Hiding the strip for it would
    /// cost the minimap on every palette open for no overlap.
    #[test]
    fn the_palette_leaves_the_single_strip_declared() {
        use stoat_action::OpenCommandPalette;
        use stoat_config::MinimapMode;
        use stoatty_protocol::command::Command;

        let strip_declared = |cmds: &[Command]| -> bool {
            cmds.iter()
                .any(|c| matches!(c, Command::Minimap(m) if m.strip_id == u32::MAX))
        };

        let mut h = Stoat::test();
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel::<Vec<u8>>();
        h.stoat.set_apc_tx(tx);
        h.stoat.settings.editor_minimap = Some(MinimapMode::Single);
        h.resize(200, 24);

        let a = h.write_file("a.txt", "alpha\nbravo\ncharlie\n");
        h.open_file(&a);
        h.settle();

        let _ = h.stoat.render();
        h.stoat.emit_apc_scene();
        assert!(strip_declared(&drain_apc(&mut rx)));

        action_handlers::dispatch(&mut h.stoat, &OpenCommandPalette);
        h.settle();
        let _ = h.stoat.render();
        h.stoat.emit_apc_scene();
        assert!(
            h.stoat.command_palette.is_some(),
            "the palette must actually be open for this to mean anything"
        );
        assert!(
            strip_declared(&drain_apc(&mut rx)),
            "the strip survives the palette rather than vanishing under it"
        );

        h.stoat.command_palette = None;
        let _ = h.stoat.render();
        h.stoat.emit_apc_scene();
        assert!(
            strip_declared(&drain_apc(&mut rx)),
            "and stays declared once the palette closes"
        );
    }

    #[test]
    fn the_hints_box_draws_over_the_single_strip() {
        use stoat_config::MinimapMode;
        use stoatty_protocol::command::Command;

        let mut h = Stoat::test();
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel::<Vec<u8>>();
        h.stoat.set_apc_tx(tx);
        h.stoat.settings.editor_minimap = Some(MinimapMode::Single);
        h.resize(200, 24);

        let a = h.write_file("a.txt", "alpha\nbravo\ncharlie\n");
        h.open_file(&a);
        h.settle();

        // The which-key box is standing hints, not a centered modal, so the strip
        // stays declared and the box draws on top of it.
        h.type_keys("space");
        let _ = h.stoat.render();
        h.stoat.emit_apc_scene();

        let cmds = drain_apc(&mut rx);
        let strip_idx = cmds
            .iter()
            .position(|c| matches!(c, Command::Minimap(m) if m.strip_id == u32::MAX))
            .expect("the single strip stays declared under the hints box");
        let panel_idx = cmds
            .iter()
            .position(|c| matches!(c, Command::Panel(_)))
            .expect("the hints box emits a panel");
        assert!(
            strip_idx < panel_idx,
            "the strip declares before the hints panel so the panel occludes their overlap"
        );
    }

    #[test]
    fn minimap_marks_diff_and_diagnostic_lines() {
        use crate::minimap::EdgeClass;
        use lsp_types::DiagnosticSeverity;
        use stoatty_protocol::command::{Command, MinimapRun};

        fn diag(line: u32, severity: DiagnosticSeverity) -> lsp_types::Diagnostic {
            lsp_types::Diagnostic {
                range: lsp_types::Range {
                    start: lsp_types::Position { line, character: 0 },
                    end: lsp_types::Position { line, character: 1 },
                },
                severity: Some(severity),
                ..Default::default()
            }
        }

        // The leading run of buffer line `n` in the most recent emit.
        fn line_lead(cmds: &[Command], n: u32) -> Option<MinimapRun> {
            cmds.iter().rev().find_map(|cmd| match cmd {
                Command::MinimapLines(l) => {
                    let idx = n.checked_sub(l.start)? as usize;
                    l.lines.get(idx).and_then(|runs| runs.first().copied())
                },
                _ => None,
            })
        }

        let mut h = Stoat::test();
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel::<Vec<u8>>();
        h.stoat.set_apc_tx(tx);

        let root = std::path::PathBuf::from("/minimap-marks");
        let path = root.join("a.txt");
        h.fake_fs().insert_file(&path, b"keep\nnew\ntail\n");
        h.stoat.active_workspace_mut().git_root = root;
        action_handlers::dispatch(&mut h.stoat, &OpenFile { path: path.clone() });
        h.settle();

        let buffer_id = h.stoat.focused_editor_ids().expect("editor").1;
        {
            let base = "keep\nold\ntail\n";
            let text = "keep\nnew\ntail\n";
            let dm = crate::diff_map::DiffMap::from_structural_changes(
                stoat_language::structural_diff::diff(base, text),
                Arc::new(base.to_string()),
                text,
            );
            h.stoat
                .active_workspace()
                .buffers
                .get(buffer_id)
                .expect("buffer")
                .write()
                .expect("poisoned")
                .diff_map = Some(dm);
        }
        h.stoat
            .active_workspace_mut()
            .panes
            .resize(Rect::new(0, 0, 80, 24));

        let modified = h.stoat.minimap_class_table.edge_class(EdgeClass::Modified);
        let error = h.stoat.minimap_class_table.edge_class(EdgeClass::Error);

        let _ = h.stoat.render();
        h.stoat.emit_apc_scene();
        h.stoat.emit_minimap();
        let first = drain_apc(&mut rx);
        assert_eq!(
            line_lead(&first, 1).map(|r| r.class),
            Some(modified),
            "the modified line leads with the modified edge class, got {first:?}"
        );

        h.seed_diagnostics(path.clone(), vec![diag(1, DiagnosticSeverity::ERROR)]);
        let _ = h.stoat.render();
        h.stoat.emit_minimap();
        let errored = drain_apc(&mut rx);
        assert_eq!(
            line_lead(&errored, 1).map(|r| r.class),
            Some(error),
            "an error overrides the diff mark, got {errored:?}"
        );

        h.seed_diagnostics(path.clone(), vec![]);
        let _ = h.stoat.render();
        h.stoat.emit_minimap();
        let cleared = drain_apc(&mut rx);
        assert_eq!(
            line_lead(&cleared, 1).map(|r| r.class),
            Some(modified),
            "clearing the diagnostic reverts to the modified mark, got {cleared:?}"
        );
        let touched: Vec<u32> = cleared
            .iter()
            .filter_map(|c| match c {
                Command::MinimapLines(l) => Some(l.start),
                _ => None,
            })
            .collect();
        assert_eq!(touched, vec![1], "only the formerly-marked line re-splices");

        // A recomputed diff moves the hunk to line 2 with the buffer untouched,
        // so line 2 has to pick up a mark it has never carried before.
        {
            let base = "keep\nnew\nold\n";
            let text = "keep\nnew\ntail\n";
            let dm = crate::diff_map::DiffMap::from_structural_changes(
                stoat_language::structural_diff::diff(base, text),
                Arc::new(base.to_string()),
                text,
            );
            h.stoat
                .active_workspace()
                .buffers
                .get(buffer_id)
                .expect("buffer")
                .write()
                .expect("poisoned")
                .diff_map = Some(dm);
        }
        let _ = h.stoat.render();
        h.stoat.emit_minimap();
        let moved = drain_apc(&mut rx);
        assert_eq!(
            line_lead(&moved, 2).map(|r| r.class),
            Some(modified),
            "the newly-differing line takes the modified mark, got {moved:?}"
        );
        assert_eq!(
            line_lead(&moved, 1).map(|r| r.start_col),
            Some(2),
            "line 1 matches the base again, so its lane is empty, got {moved:?}"
        );

        h.seed_diagnostics(path, vec![diag(0, DiagnosticSeverity::ERROR)]);
        let _ = h.stoat.render();
        h.stoat.emit_minimap();
        let on_clean = drain_apc(&mut rx);
        assert_eq!(
            line_lead(&on_clean, 0).map(|r| r.class),
            Some(error),
            "a diagnostic marks a line no hunk covers, got {on_clean:?}"
        );
    }

    /// The style id and interner for the first `THEME_KEYS` scope, as the
    /// production paths hand them to a token channel.
    ///
    /// Tokens must intern through the shared table, since that is what the
    /// minimap's class lookup is keyed by.
    fn first_scope_style(
        stoat: &Stoat,
    ) -> (
        HighlightStyleId,
        Arc<crate::display_map::highlights::HighlightStyleInterner>,
    ) {
        let style = stoat
            .syntax_styles
            .id_for_highlight(stoat_language::HighlightId(0))
            .expect("the first theme key resolves");
        (style, stoat.syntax_styles.interner.clone())
    }

    #[test]
    fn minimap_colors_align_past_a_leading_tab() {
        use crate::display_map::highlights::SemanticTokenHighlight;
        use std::sync::Arc;
        use stoatty_protocol::command::Command;

        let mut h = Stoat::test();
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel::<Vec<u8>>();
        h.stoat.set_apc_tx(tx);

        let root = std::path::PathBuf::from("/minimap-tab");
        let path = root.join("a.txt");
        h.fake_fs().insert_file(&path, b"\tfoo\nbar\n");
        h.stoat.active_workspace_mut().git_root = root;
        action_handlers::dispatch(&mut h.stoat, &OpenFile { path });
        h.settle();

        let (editor_id, buffer_id) = {
            let ids = h.stoat.focused_editor_ids().expect("editor");
            (ids.0, ids.1)
        };

        // Give the token a real syntax scope so it maps to a class.
        let (style, interner) = first_scope_style(&h.stoat);
        let expected_class = h.stoat.minimap_class_table.class_of(style);
        assert_ne!(
            expected_class, 0,
            "the test style must map to a syntax class"
        );

        let range = {
            let shared = h
                .stoat
                .active_workspace()
                .buffers
                .get(buffer_id)
                .expect("buffer");
            let snap = shared.read().expect("poisoned").snapshot.clone();
            snap.anchor_at(1, Bias::Right)..snap.anchor_at(4, Bias::Left)
        };
        let tokens: Arc<[SemanticTokenHighlight]> =
            Arc::from(vec![SemanticTokenHighlight { range, style }]);
        h.stoat.active_workspace_mut().editors[editor_id]
            .display_map
            .set_semantic_token_highlights(buffer_id, tokens, interner);

        h.stoat
            .active_workspace_mut()
            .panes
            .resize(Rect::new(0, 0, 80, 24));
        let _ = h.stoat.render();
        h.stoat.emit_apc_scene();
        h.stoat.emit_minimap();
        let cmds = drain_apc(&mut rx);

        let line0 = cmds
            .iter()
            .rev()
            .find_map(|cmd| match cmd {
                Command::MinimapLines(l) if l.start == 0 => l.lines.first().cloned(),
                _ => None,
            })
            .expect("line 0 summary");

        // The tab expands content to column 4, where the token's colored run
        // begins. The old display-chunk mapping placed the token past the raw
        // line's bytes, dropping the color.
        assert_eq!(
            line0.first().map(|run| (run.start_col, run.class)),
            Some((4, expected_class)),
            "the run starts at the tab-expanded column in the syntax class, got {line0:?}"
        );
    }

    #[test]
    fn minimap_recolors_on_syntax_toggle() {
        use crate::display_map::highlights::SemanticTokenHighlight;
        use std::sync::Arc;
        use stoatty_protocol::command::Command;

        let mut h = Stoat::test();
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel::<Vec<u8>>();
        h.stoat.set_apc_tx(tx);

        let root = std::path::PathBuf::from("/minimap-toggle");
        let path = root.join("a.txt");
        h.fake_fs().insert_file(&path, b"foo\nbar\n");
        h.stoat.active_workspace_mut().git_root = root;
        action_handlers::dispatch(&mut h.stoat, &OpenFile { path });
        h.settle();

        let (editor_id, buffer_id) = {
            let ids = h.stoat.focused_editor_ids().expect("editor");
            (ids.0, ids.1)
        };

        let (style, interner) = first_scope_style(&h.stoat);
        let colored_class = h.stoat.minimap_class_table.class_of(style);
        assert_ne!(
            colored_class, 0,
            "the test style must map to a syntax class"
        );

        let range = {
            let shared = h
                .stoat
                .active_workspace()
                .buffers
                .get(buffer_id)
                .expect("buffer");
            let snap = shared.read().expect("poisoned").snapshot.clone();
            snap.anchor_at(0, Bias::Right)..snap.anchor_at(3, Bias::Left)
        };
        let tokens: Arc<[SemanticTokenHighlight]> =
            Arc::from(vec![SemanticTokenHighlight { range, style }]);
        h.stoat.active_workspace_mut().editors[editor_id]
            .display_map
            .set_semantic_token_highlights(buffer_id, tokens, interner);
        h.stoat
            .active_workspace_mut()
            .panes
            .resize(Rect::new(0, 0, 80, 24));

        let line0_class = |cmds: &[Command]| {
            cmds.iter().rev().find_map(|cmd| match cmd {
                Command::MinimapLines(l) if l.start == 0 => l
                    .lines
                    .first()
                    .and_then(|runs| runs.first())
                    .map(|r| r.class),
                _ => None,
            })
        };

        let _ = h.stoat.render();
        h.stoat.emit_apc_scene();
        h.stoat.emit_minimap();
        let colored = drain_apc(&mut rx);
        assert_eq!(
            line0_class(&colored),
            Some(colored_class),
            "line 0 is colored under syntax highlighting, got {colored:?}"
        );

        // Toggling syntax off re-summarizes the built lines monochrome, with no
        // buffer edit.
        h.stoat.syntax_highlight = false;
        let _ = h.stoat.render();
        h.stoat.emit_minimap();
        let mono = drain_apc(&mut rx);
        assert_eq!(
            line0_class(&mono),
            Some(0),
            "the toggle recolors line 0 monochrome, got {mono:?}"
        );
    }

    /// A theme switch keeps the minimap's syntax highlighting.
    ///
    /// Classifying by resolved color meant a switch left the token's stale
    /// foreground matching nothing in the new table, so it classified 0 and the
    /// token vanished from the strip. Classifying by style id is immune,
    /// because the id names the scope rather than a color.
    #[test]
    fn minimap_keeps_its_classes_across_a_theme_switch() {
        use crate::display_map::highlights::SemanticTokenHighlight;
        use std::sync::Arc;

        let mut h = Stoat::test();
        let root = std::path::PathBuf::from("/minimap-theme");
        let path = root.join("a.txt");
        h.fake_fs().insert_file(&path, b"foo\nbar\n");
        h.stoat.active_workspace_mut().git_root = root;
        action_handlers::dispatch(&mut h.stoat, &OpenFile { path });
        h.settle();

        let (editor_id, buffer_id) = {
            let ids = h.stoat.focused_editor_ids().expect("editor");
            (ids.0, ids.1)
        };

        let (style, interner) = first_scope_style(&h.stoat);
        let expected = h.stoat.minimap_class_table.class_of(style);
        assert_ne!(expected, 0, "the test style must map to a syntax class");

        let range = {
            let shared = h
                .stoat
                .active_workspace()
                .buffers
                .get(buffer_id)
                .expect("buffer");
            let snap = shared.read().expect("poisoned").snapshot.clone();
            snap.anchor_at(0, Bias::Right)..snap.anchor_at(3, Bias::Left)
        };
        let tokens: Arc<[SemanticTokenHighlight]> =
            Arc::from(vec![SemanticTokenHighlight { range, style }]);
        h.stoat.active_workspace_mut().editors[editor_id]
            .display_map
            .set_semantic_token_highlights(buffer_id, tokens, interner);

        let row0_classes = |stoat: &mut Stoat| {
            let snapshot = stoat.active_workspace_mut().editors[editor_id]
                .display_map
                .snapshot();
            minimap_line_tokens(
                &snapshot,
                buffer_id,
                stoat.syntax_highlight,
                &stoat.minimap_class_table,
                0..1,
            )
            .remove(&0)
            .unwrap_or_default()
            .iter()
            .map(|token| token.class)
            .collect::<Vec<_>>()
        };
        assert_eq!(row0_classes(&mut h.stoat), vec![expected]);

        action_handlers::dispatch(
            &mut h.stoat,
            &stoat_action::SetTheme {
                name: "gruvbox-light".to_string(),
            },
        );

        let after = h.stoat.minimap_class_table.class_of(style);
        assert_ne!(after, 0, "the scope still has a class under the new theme");
        assert_eq!(
            row0_classes(&mut h.stoat),
            vec![after],
            "the token keeps its class instead of dropping off the strip"
        );
    }

